/**
 * The scalable 'search-link' player tier -- explicit decision (2026-09-20):
 * every player beyond the curated TRACKED_PLAYERS stars still gets
 * highlighted in article body text, but links to an on-site search
 * (/search?q=Name) instead of a dedicated profile page. Building a real
 * profile page for every roster player (8,000+) would mean mostly
 * photo-less, thin pages plus real ongoing maintenance as rosters churn
 * (trades/cuts/retirements) -- not a reasonable scope for this feature.
 *
 * Generated via scripts/generateRosterPlayers.ts (2026-09-20) -- real,
 * current rosters pulled live from ESPN's public API for NFL, NBA, MLB,
 * NHL, Premier League, Bundesliga, Serie A, Ligue 1, and MLS. Anyone
 * already in TRACKED_PLAYERS is excluded here (they get their real page,
 * not a search link -- entityLinks.tsx also enforces this at link-build
 * time, not just here, as a second safety net). Single-word names (no
 * space) are excluded too -- too high a false-positive-collision risk to
 * include without individual review at this scale.
 *
 * This is a live snapshot, not a permanently-accurate roster -- re-run the
 * generator periodically to pick up trades/cuts/retirements, same 'living
 * config' spirit as clubs.ts/players.ts.
 */
export interface RosterPlayer {
  name: string;
  searchTerms: string[];
}

